import json
import sys
import time
import urllib.request
import urllib.error

BASE = "http://localhost:8080"
OUT = "/tmp/recon"

state = {"token": None}
log = open(f"{OUT}/log.txt", "a")


def note(msg):
    log.write(msg + "\n")
    log.flush()


def get_token():
    req = urllib.request.Request(BASE + "/token", method="POST")
    with urllib.request.urlopen(req, timeout=30) as r:
        state["token"] = json.load(r)["token"]
    note("token refreshed")


def request(path, method="GET"):
    """Return (status, headers, body_text). Retries on errors until success."""
    attempt = 0
    while True:
        attempt += 1
        if state["token"] is None:
            get_token()
        req = urllib.request.Request(BASE + path, method=method)
        req.add_header("Authorization", "Bearer " + state["token"])
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                return r.status, dict(r.headers), r.read().decode()
        except urllib.error.HTTPError as e:
            body = e.read().decode(errors="replace")
            headers = dict(e.headers)
            note(f"{path} attempt {attempt}: HTTP {e.code} headers={headers} body={body[:300]}")
            if e.code == 401:
                get_token()
                continue
            if e.code == 404:
                return e.code, headers, body
            if e.code == 429 or e.code >= 500:
                wait = None
                ra = headers.get("Retry-After")
                if ra:
                    try:
                        wait = float(ra)
                    except ValueError:
                        wait = None
                if wait is None:
                    try:
                        wait = float(json.loads(body).get("retry_after", 0))
                    except Exception:
                        wait = 0
                time.sleep(max(wait, 1.0))
                continue
            time.sleep(1)
        except Exception as e:  # network-level problems: retry
            note(f"{path} attempt {attempt}: {type(e).__name__}: {e}")
            time.sleep(1)


def fetch_pages():
    pages = []
    page = 1
    total = None
    while total is None or page <= total:
        status, headers, body = request(f"/orders?page={page}")
        data = json.loads(body)
        total = data["total_pages"]
        pages.append({"page": page, "items": data["items"], "next": data.get("next")})
        note(f"page {page}/{total} ok, {len(data['items'])} items, next={data.get('next')}")
        page += 1
    return pages


def fetch_customers(ids):
    result = {}
    for cid in sorted(ids):
        status, headers, body = request(f"/customers/{cid}")
        if status == 404:
            result[cid] = None
            note(f"customer {cid}: 404")
        else:
            result[cid] = json.loads(body)
    return result


if __name__ == "__main__":
    pages = fetch_pages()
    with open(f"{OUT}/pages.json", "w") as f:
        json.dump(pages, f)
    customer_ids = {it["customer_id"] for p in pages for it in p["items"]}
    customers = fetch_customers(customer_ids)
    with open(f"{OUT}/customers.json", "w") as f:
        json.dump(customers, f)
    print("pages:", len(pages), "items:", sum(len(p["items"]) for p in pages),
          "customers:", len(customers), "missing:", sum(1 for v in customers.values() if v is None))

